 5	final class PrimsMinimumSpanningTree {
 6	    private PrimsMinimumSpanningTree() {
 7	    }
 8	
 9	    static MstResult compute(WeightedGraph graph) {
10	        int vertexCount = graph.vertexCount();
11	        int[] parentByVertex = new int[vertexCount];
12	        int[] bestWeightByVertex = new int[vertexCount];
13	        boolean[] includedInTree = new boolean[vertexCount];
14	
15	        Arrays.fill(parentByVertex, -1);
16	        Arrays.fill(bestWeightByVertex, Integer.MAX_VALUE);
17	        bestWeightByVertex[0] = 0;
18	
19	        for (int visitedVertices = 0; visitedVertices < vertexCount; visitedVertices++) {
20	            int currentVertex = selectNextVertex(bestWeightByVertex, includedInTree);
21	            if (currentVertex == -1) {
22	                throw new IllegalStateException("Graph must be connected.");
23	            }
24	
25	            includedInTree[currentVertex] = true;
26	            relaxAdjacentVertices(graph, currentVertex, parentByVertex, bestWeightByVertex, includedInTree);
27	        }
28	
29	        return buildResult(graph, parentByVertex);
30	    }
31	
32	    private static int selectNextVertex(int[] bestWeightByVertex, boolean[] includedInTree) {
33	        int lightestWeight = Integer.MAX_VALUE;
34	        int selectedVertex = -1;
35	
36	        for (int vertex = 0; vertex < includedInTree.length; vertex++) {
37	            if (!includedInTree[vertex] && bestWeightByVertex[vertex] < lightestWeight) {
38	                lightestWeight = bestWeightByVertex[vertex];
39	                selectedVertex = vertex;
40	            }
41	        }
42	
43	        return selectedVertex;
44	    }
45	
46	    private static void relaxAdjacentVertices(
47	            WeightedGraph graph,
48	            int currentVertex,
49	            int[] parentByVertex,
50	            int[] bestWeightByVertex,
51	            boolean[] includedInTree) {
52	        for (int candidateVertex = 0; candidateVertex < graph.vertexCount(); candidateVertex++) {
53	            if (!graph.hasEdge(currentVertex, candidateVertex) || includedInTree[candidateVertex]) {
54	                continue;
55	            }
56	
57	            int candidateWeight = graph.weightBetween(currentVertex, candidateVertex);
58	            if (candidateWeight < bestWeightByVertex[candidateVertex]) {
59	                parentByVertex[candidateVertex] = currentVertex;
60	                bestWeightByVertex[candidateVertex] = candidateWeight;
61	            }
62	        }
63	    }
64	
65	    private static MstResult buildResult(WeightedGraph graph, int[] parentByVertex) {
66	        List<Edge> edges = new ArrayList<>();
67	
68	        for (int vertex = 1; vertex < graph.vertexCount(); vertex++) {
69	            int parentVertex = parentByVertex[vertex];
70	            if (parentVertex == -1) {
71	                throw new IllegalStateException("Graph must be connected.");
72	            }
73	
74	            edges.add(new Edge(parentVertex, vertex, graph.weightBetween(parentVertex, vertex)));
75	        }
76	
77	        return new MstResult(edges);
78	    }
79	}

